import sqlite3

def rata_pesanan_per_pelanggan(c):
    q = '''
    SELECT round(AVG(n), 4), MAX(n) FROM (
        SELECT COUNT(*) AS n
        FROM pesanan p JOIN pelanggan g ON g.id = p.pelanggan_id
        GROUP BY g.id
    ) AS per_pelanggan
    '''
    return c.execute(q).fetchone()
